// sales-context/src/quote/QuoteService.ts
import { TaxableItem, TaxCalculationResult } from 'external-tax-sdk';

export class QuoteService {
  async calculateQuoteTax(quote: Quote): Promise<TaxCalculationResult> {
    const taxItems: TaxableItem[] = quote.lineItems.map(li => ({
      commodityCode: li.product.commodityCode,  // tax concept in Sales model
      taxJurisdiction: quote.customer.jurisdiction, // tax concept in Sales model
      lineNetAmount: li.negotiatedPrice.amount,
    }));
    // returns raw external SDK type to rest of Sales context
    return this.taxClient.calculate(taxItems);
  }

  async submitQuote(quote: Quote) {
    const taxResult = await this.calculateQuoteTax(quote);
    // rest of Sales uses TaxCalculationResult directly
    quote.taxSummary = taxResult; // external SDK type stored on aggregate
  }
}
